    '<h3 style="color:var(--gold);">Karten nach Manakosten</h3>\n        <div style="font-size:11px;color:var(--text-dim);margin-bottom:6px;">Für jede Karte zählen nur Spiele, in denen sie im Deck war. Verglichen wird die Winrate der Spiele, in denen sie <b>früh gezogen</b> wurde (Starthand nach Mulligan oder eine der nächsten {0} Karten), mit denen, in denen nicht (Δ in Prozentpunkten). Ob man eine Karte früh zieht, entscheidet allein das Mischen – anders als „gespielt“ hängt es nicht davon ab, ob man gerade vorne liegt. So hat eine Karte auch keinen Vorteil nur dadurch, dass sie in einem starken Deck steckt. Mindestens {1} Spiele je Gruppe; blasse Zeilen liegen im Zufallsbereich.</div>': '<h3 style="color:var(--gold);">Cards by mana cost</h3>\n        <div style="font-size:11px;color:var(--text-dim);margin-bottom:6px;">For each card only games in which it was in the deck count. The win rate of games in which it was <b>drawn early</b> (opening hand after mulligan or one of the next {0} cards) is compared with those in which it was not (Δ in percentage points). Whether a card is drawn early is decided by the shuffle alone – unlike “played”, it doesn\'t depend on whether you are already ahead. So a card gets no advantage just from being in a strong deck either. At least {1} games per group; faded rows are within random variation.</div>',
