    'Karte spielen': 'Play card',
    'Tippen: hinzufügen · „−“ in der Deckliste: entfernen': 'Tap: add · “−” in the deck list: remove',
    'Karten ziehen zum Ausspielen · gedrückt halten: Karte groß ansehen': 'Drag cards to play them · press and hold: view a card large',
    'Karten ziehen oder anklicken zum Ausspielen · Maus darüber: Karte groß ansehen': 'Drag or click cards to play them · hover: view a card large',
    '🎯 All-Cards Test': '🎯 All-Cards Test',
    '📖 Lerne die Regeln': '📖 Learn the rules',
    '🎓 Tutorial-Match starten (ca. 2 Min.)': '🎓 Start tutorial match (about 2 min)',
    '✕ Zurück – neues Spiel': '✕ Back – new game',
    'Das ist dein Held – unten rechts steht sein Leben. Ziel des Spiels: Bring den gegnerischen Helden (oben) auf 0 Leben.': 'This is your hero – its health is at the bottom right. Goal of the game: bring the opposing hero (top) to 0 health.',
    'Ressourcen sind dein Mana. Einmal pro Zug legst du eine beliebige Handkarte als Ressource ab. Ziehe diese Karte auf deine Ressourcen.': 'Resources are your mana. Once per turn you put any card from your hand into play as a resource. Drag this card onto your resources.',
    'Die Zahl oben links sind die Kosten. Du hast jetzt 4 Mana – ziehe den Ally auf dein Spielfeld.': 'The number at the top left is the cost. You now have 4 mana – drag the ally onto your battlefield.',
    'Neue Allies müssen eine Runde warten, bevor sie angreifen. Kor ist schon bereit: Ziehe ihn auf den gegnerischen Ally, um anzugreifen.': 'New allies have to wait a turn before they can attack. Kor is already ready: drag him onto the opposing ally to attack.',
    'Beide fügen sich gleichzeitig Schaden zu: Angriff (unten links) gegen Leben (unten rechts). Araelun ist zerstört, Kor überlebt. Wer angreift, wird erschöpft (quer) – bis zu deinem nächsten Zug.': 'Both deal damage to each other at the same time: attack (bottom left) against health (bottom right). Araelun is destroyed, Kor survives. An attacker becomes exhausted (turned sideways) until your next turn.',
    'Fähigkeiten wirken sofort und kommen danach in den Friedhof. Ziehe Fire Blast auf den gegnerischen Helden.': 'Abilities take effect immediately and then go to the graveyard. Drag Fire Blast onto the opposing hero.',
    'Dein Mana ist verbraucht. Beende deinen Zug.': 'Your mana is used up. End your turn.',
    'Der Gegner ist am Zug …': 'It\'s your opponent\'s turn …',
    'Dein neuer Zug: Alle Karten sind wieder bereit, und du hast eine Karte gezogen. Greife mit beiden Allies den gegnerischen Helden an!': 'Your new turn: all your cards are ready again and you drew a card. Attack the opposing hero with both allies!',
    'Lies den Hinweis und drücke „Weiter“.': 'Read the hint and press “Next”.',
    'Folge dem Hinweis – die markierte Aktion.': 'Follow the hint – the highlighted action.',
    '🎉 Geschafft!': '🎉 Well done!',
    'Du kennst jetzt die Grundlagen: Ressourcen legen, Karten spielen, angreifen. Mehr steht in den Erklärungen zu den Schlüsselwörtern (Maus über eine Karte bzw. gedrückt halten) und in den Videos.': 'You now know the basics: placing resources, playing cards, attacking. More is explained in the keyword boxes (hover over a card or press and hold it) and in the videos.',
    '📖 Lern-Menü': '📖 Learn menu',
    'Weiter ▶': 'Next ▶',
    'Tutorial beenden': 'End tutorial',
    'Tutorial · Schritt {0} von {1}': 'Tutorial · step {0} of {1}',
    'Das ist dein Held – unten rechts steht sein Leben. Der Gegner (oben) ist schon angeschlagen: Bring ihn auf 0 Leben, dann gewinnst du.': 'This is your hero – its health is at the bottom right. Your opponent (top) is already wounded: bring them to 0 health and you win.',
    'Für Karten brauchst du Mana – das sind deine Ressourcen. Einmal pro Zug legst du eine Karte als Ressource. Quests legst du dafür offen ab: Ziehe die Quest nach unten links auf deine Ressourcen.': 'Cards cost mana – that\'s your resources. Once per turn you place a card as a resource. Quests are placed face up: drag the quest to your resources at the bottom left.',
    'Du hast jetzt 1 Mana. Die Zahl oben links sind die Kosten – Cerwyn kostet 1. Ziehe ihn auf dein Spielfeld.': 'You now have 1 mana. The number at the top left is the cost – Cerwyn costs 1. Drag him onto your battlefield.',
    'Neue Allies müssen eine Runde warten, bevor sie angreifen. Mehr geht in diesem Zug nicht – beende deinen Zug.': 'New allies have to wait a turn before they can attack. There\'s nothing more to do this turn – end your turn.',
    'Neuer Zug: Deine Karten sind wieder bereit, und du hast eine Karte gezogen. Keine Quest auf der Hand? Jede Karte kann eine Ressource sein – sie wird verdeckt abgelegt. Ziehe Valanos auf deine Ressourcen.': 'New turn: your cards are ready again and you drew a card. No quest in hand? Any card can be a resource – it\'s placed face down. Drag Valanos onto your resources.',
    'Jetzt hast du 2 Mana. Fähigkeiten wirken sofort und kommen danach in den Friedhof. Ziehe Fire Blast auf den gegnerischen Helden.': 'Now you have 2 mana. Abilities take effect immediately and then go to the graveyard. Drag Fire Blast onto the opposing hero.',
    'Cerwyn ist jetzt bereit. Ziehe ihn auf den gegnerischen Helden, um anzugreifen – die Zahl unten links ist sein Angriffswert (ATK).': 'Cerwyn is ready now. Drag him onto the opposing hero to attack – the number at the bottom left is his attack value (ATK).',
    'Dein Held': 'Your Hero',
    'Held des Gegners': 'Enemy Hero',
    'Ausgelöste Effekte': 'Triggered effects',
    'Mehrere ausgelöste Effekte: Welcher kommt zuerst auf die Kette (löst zuletzt auf)?': 'Several triggered effects: which goes on the chain first (resolves last)?',
    '⚡ Priorität: Automatisch': '⚡ Priority: Automatic',
    '✋ Priorität: Jedes Fenster': '✋ Priority: Every window',
    'Automatisch: das Spiel hält nur an, wenn ein Instant, eine Kraft oder Quest gerade sinnvoll ist. Jedes Fenster: Anhalten in jedem Prioritätsfenster, in dem du etwas tun kannst.': 'Automatic: the game only pauses when an instant, power or quest is worth using right now. Every window: pause in every priority window in which you can do something.',
